package com.huy.enterprise.company;
import com.huy.enterprise.common.enums.RecordStatus; import jakarta.validation.constraints.*; import java.util.UUID;
record CompanyRequest(@NotBlank String name,String taxCode,@Email String email,String phone,String address,RecordStatus status){} record CompanyResponse(UUID id,String name,String taxCode,String email,String phone,String address,RecordStatus status){static CompanyResponse from(Company c){return new CompanyResponse(c.getId(),c.getName(),c.getTaxCode(),c.getEmail(),c.getPhone(),c.getAddress(),c.getStatus());}}
record DepartmentRequest(@NotNull UUID companyId,@NotBlank String name,@NotBlank String code,String description,RecordStatus status){} record DepartmentResponse(UUID id,UUID companyId,String name,String code,String description,RecordStatus status){static DepartmentResponse from(Department d){return new DepartmentResponse(d.getId(),d.getCompany().getId(),d.getName(),d.getCode(),d.getDescription(),d.getStatus());}}
record EmployeeRequest(@NotNull UUID companyId,UUID departmentId,UUID userId,@NotBlank String employeeCode,@NotBlank String fullName,@Email String email,String phone,String jobTitle,RecordStatus status){} record EmployeeResponse(UUID id,UUID companyId,UUID departmentId,UUID userId,String employeeCode,String fullName,String email,String phone,String jobTitle,RecordStatus status){static EmployeeResponse from(Employee e){return new EmployeeResponse(e.getId(),e.getCompany().getId(),e.getDepartment()==null?null:e.getDepartment().getId(),e.getUser()==null?null:e.getUser().getId(),e.getEmployeeCode(),e.getFullName(),e.getEmail(),e.getPhone(),e.getJobTitle(),e.getStatus());}}
